INSERT INTO `wp_huge_itportfolio_images` (`id`, `name`, `portfolio_id`, `description`, `image_url`, `sl_url`, `sl_type`, `link_target`, `ordering`, `published`, `published_in_sl_width`, `category`) VALUES
(10, 'StudyProg', '2', 'The idea of creating a Studyprog project appeared in October of 2012. Initially, the development of the project was attended by undergraduate of the Baku branch of Moscow State University named after M. V. Lomonosov Alexander Proskuryakov, who create a primary version of testing system and student of this University Ali Veliyev. The first release of the project took place on 14 September 2013. The site Studyprog can find educational materials on the theory of algorithms and programming. Also, the site operates channel on Youtube, which are also published video tutorials, as well as footage from various events.\r\n\r\nNow development and support of site and testing system makes by Ali Veliyev.', 'http://aliveliyev.com/wp-content/uploads/2016/06/sp1.png;', 'http://studyprog.com/', '', '0', 1, 2, 1, ''),
(11, 'AkkuGreissler LiFePO4 motorcycle battery systems', '2', '', 'http://aliveliyev.com/wp-content/uploads/2016/06/ak1.png;', 'http://akkugreissler.com/', '', '0', 0, 2, 1, '');
